/** @typedef {Readonly<Record<string, unknown>>} __puiRawProps */
/** @typedef {Readonly<GeneratedProps & Record<string, unknown>>} __puiResolvedProps */
/** @typedef {{ changedKeysAll: string[], changedKeysMatched: string[] }} __puiPropsWatchInfo */
/** @template Run @template Snapshot @typedef {(run: Run, next: Snapshot, previous: Snapshot, info: __puiPropsWatchInfo) => void} __puiPropsWatchCallback */
/** @template Run @typedef {{ kind: 'resolved' | 'resolved-all', keys: readonly string[] | null, fn: __puiPropsWatchCallback<Run, __puiResolvedProps> } | { kind: 'raw' | 'raw-all', keys: readonly string[] | null, fn: __puiPropsWatchCallback<Run, __puiRawProps> }} __puiPropsWatchRegistration */

/** @type {__puiResolvedProps} */
const snapshot = Object.freeze(out);
return { snapshot, meta };

if (changedKeysMatched.length) {
  const info = { changedKeysAll: [...changedKeysAll], changedKeysMatched: [...changedKeysMatched] };
  // The registration discriminant preserves the raw/resolved callback
  // relation; the host group order and snapshot copies stay unchanged.
  if (watch.kind === 'raw' || watch.kind === 'raw-all') watch.fn(run, nextRaw, previousRaw, info);
  else watch.fn(run, next.snapshot, previous, info);
}

/** @param {readonly string[]} keys @param {__puiPropsWatchCallback<typeof run, __puiResolvedProps>} fn */
watch: (keys, fn) => registerPropsWatch({ kind: 'resolved', keys, fn }),
/** @param {__puiPropsWatchCallback<typeof run, __puiResolvedProps>} fn */
watchAll: (fn) => registerPropsWatch({ kind: 'resolved-all', keys: null, fn }),
/** @param {readonly string[]} keys @param {__puiPropsWatchCallback<typeof run, __puiRawProps>} fn */
watchRaw: (keys, fn) => registerPropsWatch({ kind: 'raw', keys, fn }),
/** @param {__puiPropsWatchCallback<typeof run, __puiRawProps>} fn */
watchRawAll: (fn) => registerPropsWatch({ kind: 'raw-all', keys: null, fn }),
